"""Run exactly one next JVM from the unchanged frozen direct-memo protocol.

Every preceding slot needs complete validated raw output and a durable normal
completion receipt. An incomplete attempt permanently blocks this cohort. No
fork is retried, replaced, skipped, or imported from another cohort.
"""
import argparse
import fcntl
import hashlib
import importlib.util
import json
import os
from pathlib import Path
import signal
import statistics
import sys
import time

HERE = Path(__file__).resolve().parent
PHASE = HERE.parent
ROOT = PHASE.parents[1]
BENCHMARK = PHASE / 'benchmark'
PROTOCOL = BENCHMARK / 'frozen-protocol-v1.json'
PROTOCOL_SHA = '8140db1dafa30ff1121e56284837b52b7a395464f656a7f3eecf9eea8f0fcc84'
RUNTIME_SHA = 'cf4336e8ce853bc3f4a604f0f29b4e3c9acfcff4751ea0b028c78e71f98d8115'
RAW_FILES = ('command.json', 'process-result.json', 'console.log', 'samples.jsonl',
             'root-host-audit.json', 'direct-memo-statistics.jsonl', 'validation.json')


def require(condition, message):
    if not condition:
        raise ValueError(message)


def sha(path):
    digest = hashlib.sha256()
    with Path(path).open('rb') as stream:
        for block in iter(lambda: stream.read(1 << 20), b''):
            digest.update(block)
    return digest.hexdigest()


def read(path):
    return json.loads(Path(path).read_text())


def write(path, value, *, replace=False):
    """Small durable receipts; derived summaries may be regenerated, raw receipts may not."""
    path = Path(path)
    with path.open('w' if replace else 'x') as stream:
        json.dump(value, stream, indent=2, sort_keys=True)
        stream.write('\n')
        stream.flush()
        os.fsync(stream.fileno())


def pinned(path, expected):
    path = Path(path).resolve(strict=True)
    require(sha(path) == expected, 'Pinned file changed: ' + str(path))
    return path


def driver_for(protocol):
    path = pinned(protocol['driverFile'], protocol['driverFileSha256'])
    pinned(protocol['identityHelperFile'], protocol['identityHelperFileSha256'])
    sys.path.insert(0, str(path.parent))
    spec = importlib.util.spec_from_file_location('frozen_direct_memo_driver', path)
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return module


def schedule_for(driver, protocol, runtime, cohort):
    schedule = []
    for round_index, order in enumerate(protocol['balancedOrders']):
        for fixture_position, fixture in enumerate(protocol['fixtureOrdersByRound'][round_index]):
            for position, arm in enumerate(order):
                folder = cohort / f'round-{round_index:02d}-{fixture_position:02d}-{fixture}-{position:02d}-{arm}'
                properties = driver.arm_properties(protocol, fixture, arm)
                command = [driver.JAVA, *driver.JVM, *['-D' + k + '=' + v for k, v in properties.items()],
                    '-cp', runtime['classpath'], driver.QUALIFIED_LAUNCHER, fixture, '--arm=' + arm,
                    '--source=' + runtime['descriptor']['sourceIdentity'], '--warmup=8', '--iterations=5',
                    *driver.FIXTURES[fixture]['arguments'], '--consumption=full',
                    '--output=' + str(folder / 'samples.jsonl'), '--store=' + str(folder / 'store')]
                schedule.append({'ordinal': len(schedule), 'round': round_index, 'fixture': fixture,
                    'fixturePosition': fixture_position, 'position': position, 'arm': arm,
                    'directory': str(folder), 'command': command})
    require(len(schedule) == 36, 'Frozen schedule must have exactly36 slots')
    return schedule


def initialize(args):
    protocol = read(pinned(PROTOCOL, PROTOCOL_SHA))
    require(protocol['runtimeDescriptorFileSha256'] == RUNTIME_SHA, 'Wrong qualified runtime')
    driver = driver_for(protocol)
    protocol, runtime = driver.validate_protocol(PROTOCOL)  # Full immutable-runtime check, before any JVM.
    cohort = args.cohort.resolve()
    cohort.mkdir(parents=True, exist_ok=False)
    (cohort / 'slot-claims').mkdir()
    (cohort / 'used-protocol.json').write_bytes(PROTOCOL.read_bytes())
    consumed = cohort / 'runtime-identity'
    consumed.mkdir()
    write(consumed / 'runtime-descriptor.json', runtime['descriptor'])
    watched = {str(PROTOCOL): PROTOCOL_SHA,
        str(Path(__file__).resolve()): sha(__file__), str(HERE / 'README.md'): sha(HERE / 'README.md'),
        **{protocol[k]: protocol[k + 'Sha256'] for k in
           ('driverFile', 'identityHelperFile', 'independentAnalysisFile', 'protocolDocumentFile', 'runtimeDescriptorFile')},
        **runtime['sourceFiles'], str(driver.COMMON_FILE): driver.COMMON_SHA}
    for group in ('inputs', 'baseInputs'):
        for key, path in runtime[group].items():
            watched[str(path)] = sha(path)
            (consumed / (group + '-' + key + '-' + path.name)).write_bytes(path.read_bytes())
    write(cohort / 'preflight.json', {'protocolSha256': PROTOCOL_SHA,
        'runtimeManifest': runtime['manifest'], 'watchedFiles': watched,
        'overlayClassFiles': runtime['overlayClassFiles']})
    interruption = args.interruption_audit.resolve(strict=True)
    state = {'format': 1, 'cohort': str(cohort), 'frozenEpochNs': time.time_ns(),
        'protocolFile': str(PROTOCOL), 'protocolSha256': PROTOCOL_SHA,
        'controllerFile': str(Path(__file__).resolve()), 'controllerSha256': sha(__file__),
        'readmeFile': str(HERE / 'README.md'), 'readmeSha256': sha(HERE / 'README.md'),
        'preflightSha256': sha(cohort / 'preflight.json'),
        'runtime': {'descriptor': runtime['descriptor'], 'classpath': runtime['classpath'],
                    'manifest': runtime['manifest'], 'overlayClassFiles': runtime['overlayClassFiles']},
        'schedule': schedule_for(driver, protocol, runtime, cohort),
        'excludedPriorCohortAudit': {'path': str(interruption), 'sha256': sha(interruption)},
        'supervision': 'One next JVM per invocation, followed by exit; root separately observes tool exit0.',
        'failurePolicy': 'Missing terminal receipt, partial output, failed qualification, gaps, or extra slots stop the cohort permanently. No retries or replacements.',
        'timingPolicy': 'Original Java commands, ordering,13queries,300second deadline, gates, and analysis unchanged. No added cooling, sleep, or pause rule.',
        'hashingPolicy': 'Full runtime hashes at initialization and final completion only; small identity files, prefix classes, and preceding raw records checked between forks.',
        'pooling': 'Entirely fresh36-JVM cohort; no data from the interrupted cohort is imported.'}
    write(cohort / 'supervision.json', state)
    write(cohort / 'runs.json', [])
    write(cohort / 'summary.json', driver.summary([], False, [], []))
    print(json.dumps({'initialized': str(cohort), 'supervisionSha256': sha(cohort / 'supervision.json'),
                      'protocolSha256': PROTOCOL_SHA, 'jvmsLaunched': 0}))


def load_state(cohort):
    state = read(cohort / 'supervision.json')
    require(state['format'] == 1 and state['cohort'] == str(cohort), 'Unexpected supervision identity')
    pinned(__file__, state['controllerSha256'])
    pinned(state['readmeFile'], state['readmeSha256'])
    protocol = read(pinned(state['protocolFile'], PROTOCOL_SHA))
    require(state['protocolSha256'] == PROTOCOL_SHA
            and sha(cohort / 'used-protocol.json') == PROTOCOL_SHA, 'Consumed frozen protocol changed')
    require(protocol['runtimeDescriptorFileSha256'] == RUNTIME_SHA, 'Qualified runtime changed')
    preflight = read(pinned(cohort / 'preflight.json', state['preflightSha256']))
    for path, digest in preflight['watchedFiles'].items():
        pinned(path, digest)  # Source/descriptor/manifest files, not classpath jars or full class trees.
    pinned(state['excludedPriorCohortAudit']['path'], state['excludedPriorCohortAudit']['sha256'])
    driver = driver_for(protocol)
    driver.validate_design(protocol)
    require(state['runtime']['descriptor'] == protocol['runtime'], 'Runtime descriptor differs from freeze')
    require(state['schedule'] == schedule_for(driver, protocol, state['runtime'], cohort), 'Frozen commands changed')
    require(driver.identity.tree_files(state['runtime']['manifest'][0]['path'])
            == state['runtime']['overlayClassFiles'], 'Experimental six-class prefix changed')
    require(not (cohort / 'supervision-failure.json').exists(), 'This cohort has a permanent supervision failure')
    for key in ('JAVA_TOOL_OPTIONS', 'JDK_JAVA_OPTIONS', '_JAVA_OPTIONS'):
        require(not os.environ.get(key), 'Unprescribed JVM environment: ' + key)
    return state, protocol, driver, preflight


def require_prefix(schedule, directory_names, claim_names):
    """A claim without a complete predecessor can never be selected again."""
    count = len(claim_names)
    require(count <= len(schedule), 'Extra attempted slot')
    require(set(claim_names) == {f'slot-{i:02d}.json' for i in range(count)}, 'Missing, duplicate, or extra slot claim')
    require(set(directory_names) == {Path(slot['directory']).name for slot in schedule[:count]},
            'Missing, unclaimed, or extra slot directory')
    return count


def read_run(driver, protocol, runtime, slot):
    folder = Path(slot['directory'])
    command, process = read(folder / 'command.json'), read(folder / 'process-result.json')
    require(command['argv'] == slot['command'] and command['cwd'] == str(ROOT), 'Actual Java command changed')
    require(process['exitCode'] == 0 and process['failure'] is None
            and process['startedEpochNs'] == command['startedEpochNs']
            and process['finishedEpochNs'] >= process['startedEpochNs'], 'JVM did not terminate normally')
    metadata, samples, audit, measured, validation, accounting = driver.validate_run(
        folder, slot['fixture'], slot['arm'], runtime, protocol, write_validation=False)
    require(validation['targetQualified'], '; '.join(validation['targetQualificationReasons']))
    if (folder / 'validation.json').exists():
        require(read(folder / 'validation.json') == validation, 'Saved validation differs from raw records')
    properties = driver.arm_properties(protocol, slot['fixture'], slot['arm'])
    return {k: slot[k] for k in ('round', 'fixture', 'fixturePosition', 'position', 'arm', 'directory')} | {
        'transportMode': properties[driver.TRANSPORT_PROPERTY],
        'directMemoEnabled': properties[driver.MEMO_PROPERTY], 'metadata': metadata, 'samples': samples,
        'rootAudit': audit, 'validation': validation, 'accounting': accounting,
        'medians': {key: statistics.median(sample[key] for sample in measured) for key in driver.METRICS},
        'counterMedians': {key: statistics.median(sample['counters'][key] for sample in measured)
                          for key, value in measured[0]['counters'].items() if isinstance(value, (int, float))},
        'adjacencyLookupHits': [sample['adjacency']['lookupHits'] for sample in measured],
        'routeTierHistogram': driver.route_histogram(measured),
        'routeTierHistogramMatchesFirstFixtureFork': True, 'processInterval': process}


def shared_gates(driver, runs):
    metadata, routes, triples, pairs = {}, {}, {}, []
    previous_end = 0
    for run in runs:
        fixture = run['fixture']
        normalized = driver.normalized_metadata(run['metadata'])
        metadata.setdefault(fixture, normalized)
        routes.setdefault(fixture, run['routeTierHistogram'])
        require(metadata[fixture] == normalized and routes[fixture] == run['routeTierHistogram'],
                'Fixture metadata or measured AUTO route/tier changed')
        process = run['processInterval']
        require(process['startedEpochNs'] >= previous_end, 'JVM process intervals overlap')
        previous_end = process['finishedEpochNs']
        triple = triples.setdefault((fixture, run['round']), {})
        require(run['arm'] not in triple, 'Duplicate arm in a fixture/round')
        triple[run['arm']] = run
        if len(triple) == 3:
            for comparator in ('ordinary', 'dense'):
                pair = driver.treatment_pair_audit(triple[comparator], triple['direct'])
                require(pair['passed'], 'Per-query routes, tiers, or adjacency changed')
                pairs.append(pair)
    return pairs


def completed_prefix(cohort, state, protocol, driver):
    directories = [path.name for path in cohort.glob('round-*')]
    claims = list((cohort / 'slot-claims').iterdir())
    require(all(path.is_file() and not path.is_symlink() for path in claims), 'Unexpected claim artifact')
    count = require_prefix(state['schedule'], directories, [path.name for path in claims])
    runs, previous_receipt = [], None
    supervision_sha = sha(cohort / 'supervision.json')
    for slot in state['schedule'][:count]:
        folder = Path(slot['directory'])
        claim_path = cohort / 'slot-claims' / f"slot-{slot['ordinal']:02d}.json"
        claim = read(claim_path)
        receipt_path = folder / 'supervisor-completion.json'
        require(receipt_path.is_file(), 'Incomplete prior slot: missing normal supervisor completion receipt')
        receipt = read(receipt_path)
        require(claim['slot'] == slot and claim['supervisionSha256'] == supervision_sha
                and claim['previousCompletionSha256'] == previous_receipt,
                'Slot claim differs from its frozen position or predecessor')
        require(receipt['completedNormally'] is True and receipt['ordinal'] == slot['ordinal']
                and receipt['supervisionSha256'] == supervision_sha
                and receipt['claimSha256'] == sha(claim_path), 'Invalid normal completion receipt')
        require(set(receipt['rawFileSha256']) == set(RAW_FILES), 'Incomplete raw-file receipt')
        for name, digest in receipt['rawFileSha256'].items():
            pinned(folder / name, digest)
        run = read_run(driver, protocol, state['runtime'], slot)
        require(receipt['controllerStartedEpochNs'] == claim['controllerStartedEpochNs']
                <= run['processInterval']['startedEpochNs']
                <= run['processInterval']['finishedEpochNs'] <= receipt['completedEpochNs'],
                'Supervisor/process chronology is invalid')
        expected_gap = None if not runs else run['processInterval']['startedEpochNs'] - runs[-1]['processInterval']['finishedEpochNs']
        require(receipt['interJvmGapNs'] == expected_gap, 'Inter-JVM gap record differs from raw process intervals')
        runs.append(run)
        previous_receipt = sha(receipt_path)
    return runs, shared_gates(driver, runs), previous_receipt


def final_preservation(driver, state, preflight):
    return {'identityFilesUnchanged': all(Path(path).is_file() and sha(path) == digest
                                        for path, digest in preflight['watchedFiles'].items()),
            'runtimeIdentityUnchanged': driver.identity.classpath_manifest(state['runtime']['classpath'])
                                        == state['runtime']['manifest']}


def next_step(args):
    require(args.slot_released, 'The coordinator must release the exclusive Java slot')
    started = time.time_ns()
    cohort = args.cohort.resolve(strict=True)
    state, protocol, driver, preflight = load_state(cohort)
    runs, pairs, previous_receipt = completed_prefix(cohort, state, protocol, driver)
    require(len(runs) < 36, 'All36 slots are complete; use audit, not another next invocation')
    slot = state['schedule'][len(runs)]
    folder = Path(slot['directory'])
    require(not folder.exists(), 'Next slot already exists; attempts cannot be retried')
    claim_path = cohort / 'slot-claims' / f"slot-{slot['ordinal']:02d}.json"
    write(claim_path, {'slot': slot, 'controllerStartedEpochNs': started,
        'supervisionSha256': sha(cohort / 'supervision.json'), 'previousCompletionSha256': previous_receipt})
    try:
        folder.mkdir()
        print(f"Starting slot {slot['ordinal'] + 1}/36: {slot['fixture']} / {slot['arm']}", flush=True)
        driver.run_fork(slot['command'], folder, protocol['timeoutSeconds'])
        run = read_run(driver, protocol, state['runtime'], slot)
        write(folder / 'validation.json', run['validation'])
        runs.append(run)
        pairs = shared_gates(driver, runs)
        complete = len(runs) == 36
        if complete:
            require(len(pairs) == 24, 'Final comparison lacks prescribed paired audits')
            post = final_preservation(driver, state, preflight)  # The one JVM has already exited.
            write(cohort / 'post-run-preservation.json', post)
            require(all(post.values()), 'Final immutable runtime/file preservation failed')
        write(cohort / 'runs.json', runs, replace=True)
        write(cohort / 'summary.json', driver.summary(runs, complete, [], pairs), replace=True)
        receipt = {'format': 1, 'completedNormally': True, 'ordinal': slot['ordinal'],
            'supervisionSha256': sha(cohort / 'supervision.json'), 'claimSha256': sha(claim_path),
            'controllerStartedEpochNs': started, 'completedEpochNs': time.time_ns(),
            'interJvmGapNs': None if len(runs) == 1 else run['processInterval']['startedEpochNs']
                            - runs[-2]['processInterval']['finishedEpochNs'],
            'rawFileSha256': {name: sha(folder / name) for name in RAW_FILES},
            'queries': 13, 'measurements': 5, 'jvmsLaunchedThisInvocation': 1,
            'rootMustObserveToolExitZeroBeforeNext': True}
        write(folder / 'supervisor-completion.json', receipt)
        print(json.dumps({'completedSlots': len(runs), 'queries': len(runs) * 13,
                          'complete': complete, 'jvmsLaunchedThisInvocation': 1}), flush=True)
    except BaseException as error:
        write(cohort / 'supervision-failure.json', {'ordinal': slot['ordinal'], 'directory': str(folder),
            'exception': type(error).__name__, 'message': str(error), 'retryAllowed': False,
            'acceptedComparisonEstimates': False})
        raise


def audit(args):
    cohort = args.cohort.resolve(strict=True)
    state, protocol, driver, preflight = load_state(cohort)
    runs, pairs, _ = completed_prefix(cohort, state, protocol, driver)
    complete = len(runs) == 36
    require(read(cohort / 'runs.json') == runs, 'Derived runs differ from raw replay')
    require(read(cohort / 'summary.json') == driver.summary(runs, complete, [], pairs),
            'Original summary differs from raw replay')
    if complete:
        post = final_preservation(driver, state, preflight)
        require(all(post.values()) and read(cohort / 'post-run-preservation.json') == post,
                'Final runtime preservation did not replay')
    print(json.dumps({'auditPassed': True, 'complete': complete, 'completedSlots': len(runs),
                      'queries': len(runs) * 13, 'jvmsLaunched': 0}))


def interrupted(signum, frame):
    raise InterruptedError('Finite controller received signal ' + str(signum))


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('mode', choices=('init', 'next', 'audit'))
    parser.add_argument('--cohort', type=Path, required=True)
    parser.add_argument('--slot-released', action='store_true')
    parser.add_argument('--interruption-audit', type=Path,
                        default=PHASE / 'review/interrupted-primary-v1.json')
    args = parser.parse_args()
    if args.mode == 'init':
        initialize(args)
        return
    # A concurrent controller cannot launch or alter this cohort. Never wait for its lock.
    with (args.cohort / 'supervision.lock').open('a') as lock:
        fcntl.flock(lock.fileno(), fcntl.LOCK_EX | fcntl.LOCK_NB)
        if args.mode == 'next':
            signal.signal(signal.SIGTERM, interrupted)
            next_step(args)
        else:
            audit(args)


if __name__ == '__main__':
    main()
